let colors = ["#ff0000", "#feb30f", "#0aa4f7", "#ffffff", "#000000"];

let border = 0;

let circles = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 100, 100);
	rectMode(CENTER);
	pixelDensity(2);
	fill(10);
	square(width / 2, height / 2, max(width, height));

	let mySize = min(width, height) / 8;

	for (let xx = border; xx <= width - border; xx += (Math.max(0.001, Math.abs(mySize / 2)) || 1)) {
		for (let yy = border; yy <= height - border; yy += (Math.max(0.001, Math.abs(mySize / 2)) || 1)) {
			//if (random(0, 1) > 0.5) 
			{
				circles.push(new TCircle(xx, yy, random([mySize/8,mySize/4,mySize/2,mySize])));
				circles.push(new TCircle(xx, yy, random([mySize/8,mySize/4,mySize/2,mySize])));
				circles.push(new TCircle(xx, yy, random([mySize/8,mySize/4,mySize/2,mySize])));
			}
		}
	}
}

function draw() {

	fill(10);
	square(width / 2, height / 2, max(width, height));

	push();
	//translate(width/10,height/10);
	//rotate(0.001*frameCount);
	for (let i = 0; i < circles.length; i++) {
		circles[i].display();
	}
	pop();

}

class TCircle {

	constructor(xc, yc, mySize) {
		this.xc = xc;
		this.yc = yc;
		this.size = mySize;
		this.color = random(colors);
		this.transp = 40 + 50 * randomGaussian();
		this.freq = random(0.05,0.01);
		//this.freq = map(this.xc,border,width-border,0.05,0.02);
		this.dir = random([-1,1]);
		this.crad = this.size/2;
		this.weight = random(0,0.5);
		this.phase = random(0,2*PI);
		this.count = floor(random(1,50));
	}

	display() {
		crystalMaterial(this.color, this.transp,this.weight);
		push();
		translate(this.xc,this.yc);
		rotate(this.freq*this.dir*frameCount);
		let myScale = 1 + cos(this.freq*frameCount + this.phase);
		if (myScale < 0.01)
		{
			this.color = random(colors);
		}
		scale(myScale);
		stroke(this.color);
		for(let ang = 0;ang <= TWO_PI;ang += (Math.max(0.001, Math.abs((TWO_PI)) || 1))/this.count)
		{
		  //if (random(0,1) > 0.5)
		  {
			  line(this.size/5*cos(ang),this.size/5*sin(ang),this.size/2*cos(ang),this.size/2*sin(ang));
		  }
		}
		//rotate(PI/2*floor(random(1,10)));

		circle(0,0, this.size);
		circle(0,0, this.size/2.5);

		pop();
	}


}

function crystalMaterial(col, transp,ww) {
	myColor = color(col);
	myColor.setAlpha(transp);
	fill(myColor);
	noStroke();
	stroke(100, 50);
	strokeWeight(ww);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}


